ruleToc.chapterName:
$.chaptername
@js:
result=result.replace(/^\s+/,'');
intro=java.getString("$.chapterintro",false);
java.put("intro",intro);
vip='{{$.isvip}}'!='0';
lock='{{$.islock}}'!='0';
type='{{$.chaptertype}}'=='1';
num=!type?'{{$.chapterid}}、':'';
